export function adaptedLessonsByProfil(profil: ProfilAdaptation) {
  return ADAPTED_LESSONS.filter((l) => l.profil === profil);
}

export function adaptedLessonBySlug(slug: string) {
  return ADAPTED_LESSONS.find((l) => l.slug === slug);
}

export function adaptedNiveauxByProfil(profil: ProfilAdaptation) {
  const niveaux = new Set(adaptedLessonsByProfil(profil).map((l) => l.niveau));
  return Array.from(niveaux);
}

export function adaptedMatieresByProfilNiveau(profil: ProfilAdaptation, niveau: string) {
  const matieres = new Set(
    ADAPTED_LESSONS.filter((l) => l.profil === profil && l.niveau === niveau).map((l) => l.matiere)
  );
  return Array.from(matieres);
}

export function adaptedLessonsByProfilNiveauMatiere(
  profil: ProfilAdaptation,
  niveau: string,
  matiere: string
) {
  return ADAPTED_LESSONS.filter(
    (l) => l.profil === profil && l.niveau === niveau && l.matiere === matiere
  );
}

